+import { Unreachable } from "./errors.ts";
+import { charge } from "./gateway.ts";
+import { sendReceipt } from "./mailer.ts";
+
+export interface Invoice {
+  customerId: string;
+  totalCents: number;
+}
+
+const ATTEMPTS = 3;
+
+const pause = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
+
+/** Charges an invoice and mails its receipt, trying again when the mail service can't be reached. Gives the charge's id. */
+export async function billInvoice(invoice: Invoice): Promise<string> {
+  for (let attempt = 1; ; attempt++) {
+    try {
+      const chargeId = await charge(invoice.customerId, invoice.totalCents);
+      await sendReceipt(invoice.customerId, chargeId);
+      return chargeId;
+    } catch (error) {
+      if (!(error instanceof Unreachable) || attempt === ATTEMPTS) throw error;
+      await pause(500 * attempt);
+    }
+  }
+}
